const { useState } = React;

function App() {
  const [page, setPage] = useState("results");
  const [sortBy, setSortBy] = useState("");
  const [nonStopOnly, setNonStopOnly] = useState(false);
  const [selectedFlight, setSelectedFlight] = useState(null);
  const [passengerName, setPassengerName] = useState("");
  const [passengerEmail, setPassengerEmail] = useState("");
  const [errors, setErrors] = useState({});
  const [loadMoreMessage, setLoadMoreMessage] = useState("");

  const flights = [
    {
      id: 1,
      airline: "Air France",
      time: "08:10 - 10:25",
      price: 210,
      nonstop: true,
      buttonText: "Select flight",
      buttonAction: () => {
        setSelectedFlight(1);
        setPage("passengerDetails");
      },
    },
    {
      id: 2,
      airline: "Lufthansa",
      time: "13:40 - 16:05",
      price: 185,
      nonstop: false,
      buttonText: "Choose",
      buttonAction: () => alert("Flight chosen: Lufthansa"),
    },
  ];

  function validatePassengerDetails() {
    const newErrors = {};
    if (!passengerName.trim()) {
      newErrors.name = "Name is required.";
    }
    if (!passengerEmail.trim()) {
      newErrors.email = "Email is required.";
    } else if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(passengerEmail)) {
      newErrors.email = "Email is invalid.";
    }
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  }

  function handlePassengerSubmit(e) {
    e.preventDefault();
    if (validatePassengerDetails()) {
      alert(`Passenger details submitted for flight ${selectedFlight}: ${passengerName}, ${passengerEmail}`);
      // Reset form and go back to results
      setPassengerName("");
      setPassengerEmail("");
      setErrors({});
      setPage("results");
      setSelectedFlight(null);
    }
  }

  const filteredFlights = flights.filter(f => (nonStopOnly ? f.nonstop : true));

  return (
    <>
      <style>{`
        * {
          box-sizing: border-box;
        }
        body {
          margin: 0;
          font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen,
            Ubuntu, Cantarell, "Open Sans", "Helvetica Neue", sans-serif;
          background: #fff;
          color: #222;
        }
        header {
          padding: 1rem 1.5rem;
          border-bottom: 2px solid #222;
          font-style: italic;
          font-weight: 600;
          font-size: 1.5rem;
          max-width: 600px;
          margin: 1rem auto 2rem auto;
        }
        main {
          max-width: 600px;
          margin: 0 auto 2rem auto;
          padding: 0 1.5rem;
        }
        .controls {
          display: flex;
          align-items: center;
          gap: 1rem;
          margin-bottom: 1.5rem;
          font-style: italic;
          font-weight: 500;
          font-size: 1rem;
        }
        select {
          font-style: italic;
          font-weight: 500;
          font-size: 1rem;
          padding: 0.3rem 0.5rem;
          border: 2px solid #222;
          border-radius: 4px;
          background: white;
          cursor: pointer;
        }
        label {
          display: flex;
          align-items: center;
          gap: 0.3rem;
          cursor: pointer;
          user-select: none;
        }
        .flight-card {
          border: 2px solid #222;
          border-radius: 6px;
          padding: 0.75rem 1rem;
          margin-bottom: 1rem;
          display: flex;
          align-items: center;
          justify-content: space-between;
          font-style: italic;
          font-weight: 500;
          font-size: 1rem;
        }
        .flight-info {
          display: flex;
          gap: 1.5rem;
          flex-grow: 1;
          align-items: center;
        }
        .flight-airline {
          min-width: 100px;
        }
        .flight-time {
          min-width: 110px;
          text-align: center;
        }
        .flight-price {
          min-width: 60px;
          text-align: right;
        }
        button {
          font-style: italic;
          font-weight: 500;
          font-size: 1rem;
          padding: 0.4rem 1rem;
          border: 2px solid #222;
          border-radius: 6px;
          background: white;
          cursor: pointer;
          transition: background-color 0.2s ease;
        }
        button:hover {
          background-color: #eee;
        }
        .load-more-container {
          text-align: center;
          margin-top: 2rem;
          font-style: italic;
          font-weight: 500;
          font-size: 1rem;
          color: #b00020;
        }
        form {
          display: flex;
          flex-direction: column;
          gap: 1rem;
          font-style: italic;
          font-weight: 500;
          font-size: 1rem;
          max-width: 400px;
          margin: 0 auto;
        }
        label > span {
          display: block;
          margin-bottom: 0.3rem;
        }
        input[type="text"], input[type="email"] {
          padding: 0.4rem 0.6rem;
          border: 2px solid #222;
          border-radius: 4px;
          font-style: italic;
          font-weight: 500;
          font-size: 1rem;
        }
        .error {
          color: #b00020;
          font-size: 0.9rem;
          margin-top: -0.6rem;
          margin-bottom: 0.6rem;
        }
        h2 {
          font-style: italic;
          font-weight: 600;
          font-size: 1.3rem;
          margin-bottom: 1rem;
          text-align: center;
        }
      `}</style>

      {page === "results" && (
        <main>
          <header>Flights to Paris</header>
          <section className="controls" aria-label="Flight sorting and filtering">
            <label htmlFor="sortBy">
              <select
                id="sortBy"
                value={sortBy}
                onChange={(e) => setSortBy(e.target.value)}
                aria-label="Sort flights by"
              >
                <option value="">Sort by</option>
                <option value="price">Price</option>
                <option value="time">Time</option>
                <option value="airline">Airline</option>
              </select>
            </label>
            <label htmlFor="nonStopOnly">
              <input
                type="checkbox"
                id="nonStopOnly"
                checked={nonStopOnly}
                onChange={(e) => setNonStopOnly(e.target.checked)}
              />
              Non-stop only
            </label>
          </section>

          {filteredFlights.map((flight) => (
            <article key={flight.id} className="flight-card">
              <div className="flight-info">
                <div className="flight-airline">{flight.airline}</div>
                <div className="flight-time">{flight.time}</div>
                <div className="flight-price">${flight.price}</div>
              </div>
              <button onClick={flight.buttonAction} aria-label={`${flight.buttonText} for ${flight.airline}`}>
                {flight.buttonText}
              </button>
            </article>
          ))}

          <div className="load-more-container">
            <button onClick={() => setLoadMoreMessage("No more flights.")}>Load more</button>
            {loadMoreMessage && <p role="alert">{loadMoreMessage}</p>}
          </div>
        </main>
      )}

      {page === "passengerDetails" && (
        <main>
          <h2>Passenger details</h2>
          <form onSubmit={handlePassengerSubmit} noValidate>
            <label htmlFor="name">
              <span>Name</span>
              <input
                type="text"
                id="name"
                value={passengerName}
                onChange={(e) => setPassengerName(e.target.value)}
                aria-describedby={errors.name ? "name-error" : undefined}
                aria-invalid={errors.name ? "true" : "false"}
              />
              {errors.name && (
                <p id="name-error" className="error" role="alert">
                  {errors.name}
                </p>
              )}
            </label>

            <label htmlFor="email">
              <span>Email</span>
              <input
                type="email"
                id="email"
                value={passengerEmail}
                onChange={(e) => setPassengerEmail(e.target.value)}
                aria-describedby={errors.email ? "email-error" : undefined}
                aria-invalid={errors.email ? "true" : "false"}
              />
              {errors.email && (
                <p id="email-error" className="error" role="alert">
                  {errors.email}
                </p>
              )}
            </label>

            <button type="submit">Submit</button>
          </form>
        </main>
      )}
    </>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);

